import 'package:discere/l10n/app_localizations.dart';
import 'package:material_ui/material_ui.dart';

/// The localizations delegates every `MaterialApp` of the app and its tests
/// uses.
///
/// `AppLocalizations.localizationsDelegates`, generated by `flutter gen-l10n`,
/// lists the Material and Cupertino delegates of `flutter_localizations`. Those
/// provide the SDK's `MaterialLocalizations`, which the `material_ui` widgets
/// do not look up, so a German app would show English tooltips, dialog
/// buttons and pickers. `GlobalMaterialLocalizations.delegates` from
/// `material_ui` pairs its own Material delegate with the matching
/// `cupertino_ui` and widgets delegates.
const List<LocalizationsDelegate<dynamic>> appLocalizationsDelegates = [
  AppLocalizations.delegate,
  ...GlobalMaterialLocalizations.delegates,
];
